def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 2 or no_water >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.25))

    highest_prev = 0.0
    eric_prev = None
    urgent_opp_count = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = 0.0
        if prev and prev.get('bid') is not None:
            bid = float(prev.get('bid', 0.0))
        if bid > highest_prev:
            highest_prev = bid
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            urgent_opp_count += 1
        if opp.get('daily_salary') == 70 and opp.get('water_requirement') == 13:
            if bid > 0:
                eric_prev = bid

    threat_bid = highest_prev
    if eric_prev is not None and eric_prev > threat_bid:
        threat_bid = eric_prev

    if supply <= 16:
        scarcity = 'tight'
    elif supply >= 22:
        scarcity = 'loose'
    else:
        scarcity = 'mid'

    if hp <= 2 or no_water >= 2:
        target = max(DAILY_SALARY * 0.95, threat_bid + 2.0)
    elif no_water >= 1:
        target = max(DAILY_SALARY * 0.82, threat_bid + 1.5)
    else:
        if scarcity == 'tight':
            target = max(DAILY_SALARY * 0.78, threat_bid + 1.0)
        elif scarcity == 'mid':
            target = max(DAILY_SALARY * 0.52, min(DAILY_SALARY * 0.9, threat_bid * 0.72 + 3.0))
        else:
            target = max(DAILY_SALARY * 0.28, min(DAILY_SALARY * 0.65, threat_bid * 0.45 + 1.0))

    if urgent_opp_count >= 2:
        target += 4.0
    elif urgent_opp_count == 1:
        target += 2.0

    if budget < DAILY_SALARY * 1.2:
        target = min(target, budget * 0.72)
    elif budget > DAILY_SALARY * 8:
        target += 2.0

    if hp >= 8 and no_water == 0 and scarcity == 'loose' and threat_bid >= DAILY_SALARY * 1.2:
        target = min(target, DAILY_SALARY * 0.35)

    bid = max(0.0, min(float(budget), float(target)))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    supply = int(day_context['supply'])
    day = int(day_context['day'])
    alive_opponents = {id: opp for id, opp in opponents_status.items() if opp['alive']}

    # Base bid: 45% of salary
    base_bid = DAILY_SALARY * 0.45

    # Adjust for supply scarcity
    if supply <= 17:
        base_bid += 10
    elif supply >= 22:
        base_bid -= 10

    # Get yesterday's max bid from alive opponents
    yesterday_bids = []
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', None)
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        # If we are desperate, bid above yesterday's max
        if my_status['no_water_days'] >= 2 or my_status['hp'] <= 3:
            target = max(max_prev + 2, DAILY_SALARY * 0.8)
        else:
            target = max_prev + 1
        # Cap at 80% of budget to avoid full depletion
        target = min(target, my_status['budget'] * 0.8)
        bid = max(base_bid, target)
    else:
        # No trace (first day or all opponents dead)
        if my_status['no_water_days'] >= 2 or my_status['hp'] <= 3:
            bid = min(my_status['budget'], DAILY_SALARY * 0.9)
        else:
            bid = min(base_bid, DAILY_SALARY * 0.75)

    # Ensure we never bid more than available budget
    bid = min(bid, my_status['budget'])
    # Ensure bid is non-negative
    bid = max(bid, 0)
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    # Alive opponents and yesterday bids
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no opponents alive, just bid conservatively
    if not alive_opps:
        return float(min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4))

    # Extract yesterday's bids for immediate pressure
    yesterday_bids = []
    alex_yesterday_bid = None
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b = float(b)
            except Exception:
                continue
            yesterday_bids.append(b)
            if oid == 'Alex':
                alex_yesterday_bid = b

    # Determine how aggressive to be
    highest_prev = max(yesterday_bids) if yesterday_bids else 0.0

    # Base bid: aim around half salary, scaled by supply pressure
    # Lower supply => bid higher to avoid water shortfall.
    supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    supply_pressure = 1.0 - max(0.0, min(1.0, supply_ratio))  # 0 (high supply) to 1 (low supply)

    # If Alex bid strongly yesterday, assume they will bid again; slightly overbid.
    if alex_yesterday_bid is not None and alex_yesterday_bid >= DAILY_SALARY * 0.85:
        # If we are healthy, try to outbid with moderate premium; if low hp, go harder.
        if my_status.get('hp', 0) > 3:
            target = DAILY_SALARY * (0.33 + 0.25 * supply_pressure)
        else:
            target = DAILY_SALARY * (0.75 + 0.15 * supply_pressure)
        # Add small premium over Alex's last bid to exploit simultaneous bidding
        target = max(target, alex_yesterday_bid + 2.0)
    else:
        # Otherwise, bid to beat timid opponents; keep cost controlled.
        # If any opponent bid high yesterday, respond proportionally.
        if highest_prev >= DAILY_SALARY * 0.7:
            target = max(DAILY_SALARY * (0.45 + 0.2 * supply_pressure), highest_prev * 0.92)
        else:
            target = DAILY_SALARY * (0.55 + 0.25 * supply_pressure)

    # Budget and hp constraints
    budget = float(my_status.get('budget', 0.0))
    hp = float(my_status.get('hp', 0.0))

    # If we are in danger, spend more (but never exceed budget)
    if hp <= 2:
        target = max(target, DAILY_SALARY * 0.9)
    elif hp <= 4:
        target = max(target, DAILY_SALARY * 0.65)

    # Ensure non-negative and within budget
    bid = float(max(0.0, min(budget, target)))

    # If budget is tiny, still bid all-in
    if budget <= 1.0:
        bid = budget

    return bid
